import { computed } from 'vue';
import { i18n } from 'src/boot/i18n';
import { Acl, FieldPermission } from 'src/core/acls/Acl';
import { useDocumentStore } from 'src/store/Document/document.store';
import { useFormBuilderStore } from 'src/store/FormBuilder/form_builder.store';
import { buildValidationBlockers } from 'src/utils/validationBlockers';
import type { ValidationBlockers } from 'src/utils/validationBlockers';

/** CORE-6161: live blocker list of the document open in the validation screen. */
export function useValidationBlockers() {
  const blockers = computed(() => buildValidationBlockersForCurrentDoc());

  return { blockers };
}

/**
 * CORE-6161 popout: one plain snapshot of the same list, so the validation
 * screen can hand the board to the assistant window. A separate window shares
 * no Pinia state with its opener, and rebuilding the form-builder model there
 * would need the heavy, write-capable load path — wrong for a read-only board.
 * `useValidationBlockers()` calls this too, so there is one source of truth.
 */
export function buildValidationBlockersForCurrentDoc(): ValidationBlockers {
  const documentStore = useDocumentStore();
  const formBuilderStore = useFormBuilderStore();

  return buildValidationBlockers({
    record: documentStore.record,
    formLayout: formBuilderStore.formLayout,
    formBuilderModel: formBuilderStore.formBuilderModel,
    formBuilderConfigModel: formBuilderStore.formBuilderConfigModel,
    t: (key, params) => (params ? i18n.t(key, params) : i18n.t(key)),
    canViewField: (fieldId) =>
      !fieldId ||
      Acl.hasFieldPermission(
        documentStore.record?.doc_type,
        fieldId,
        FieldPermission.READ_ONLY,
      ),
  });
}
